// Render the catalogue portraits as sprites; the source assets remain unchanged.
function sprite(img,key){const c=document.createElement('canvas');c.width=320;c.height=480;const g=c.getContext('2d');g.drawImage(img,0,0,320,480);const im=g.getImageData(0,0,320,480),d=im.data,seen=new Uint8Array(320*480),queue=new Int32Array(320*480);let head=0,tail=0;function add(p){if(seen[p])return;seen[p]=1;let k=p*4,r=d[k],v=d[k+1],b=d[k+2];if(key==='paster-fenrir'?(Math.max(r,v,b)-Math.min(r,v,b)<14&&r>90&&r<202):(Math.max(r,v,b)-Math.min(r,v,b)<23&&r>139&&r<235&&(key==='hattan'?v>=r-1:key==='yaoi'?(v>=r+1&&b>=r+3):['gumon','kagachi','masa','deji'].includes(key)?(v>=r&&b>=r):true))){queue[tail++]=p;d[k+3]=0}}for(let x=0;x<320;x++){add(x);add(479*320+x)}for(let y=0;y<480;y++){add(y*320);add(y*320+319)}while(head<tail){let p=queue[head++],x=p%320;if(x)add(p-1);if(x<319)add(p+1);if(p>=320)add(p-320);if(p<479*320)add(p+320)}g.putImageData(im,0,0);return c}
let jendSprite=null;const jendImg=new Image();const jendReady=new Promise((resolve,reject)=>{jendImg.onload=()=>{jendSprite=sprite(jendImg,'jend');resolve()};jendImg.onerror=reject;jendImg.src=window.ARENA_IMAGES['jend']});
const soldierImg=new Image();const soldierReady=new Promise((resolve,reject)=>{soldierImg.onload=resolve;soldierImg.onerror=reject;soldierImg.src=window.ARENA_IMAGES['diamond-soldier']});
let hydeSprite=null;const hydeImg=new Image();const hydeReady=new Promise((resolve,reject)=>{hydeImg.onload=()=>{hydeSprite=sprite(hydeImg,'hyde');resolve()};hydeImg.onerror=reject;hydeImg.src=window.ARENA_IMAGES.hyde});
const sprites=[];let fenrirSprite=null;const fenrirImg=new Image();const fenrirReady=new Promise((resolve,reject)=>{fenrirImg.onload=()=>{fenrirSprite=sprite(fenrirImg,'paster-fenrir');resolve()};fenrirImg.onerror=reject;fenrirImg.src=window.ARENA_IMAGES['paster-fenrir']});Promise.all(imgs.map((im,i)=>new Promise((resolve,reject)=>{im.onload=()=>{sprites[i]=sprite(im,roster[i].key);resolve()};im.onerror=reject;im.src=window.ARENA_IMAGES[roster[i].key]||'assets/'+roster[i].key+'.webp'})).concat(fenrirReady,soldierReady,jendReady,hydeReady)).then(()=>{loaded=true;reset()}).catch(()=>{$('message').textContent='画像を読み込めませんでした。ページを再読み込みしてください。';$('start').disabled=true});
function stamp(){return Math.floor(elapsed/60).toString().padStart(2,'0')+':'+Math.floor(elapsed%60).toString().padStart(2,'0')}
function log(s){const li=document.createElement('li');let t=document.createElement('time');t.textContent=stamp();li.append(t,document.createTextNode(s));$('log').prepend(li);while($('log').children.length>16)$('log').lastChild.remove()}
function call(s,c){$('callout').textContent=s;$('callout').style.color=c;$('callout').classList.add('show');callTimer=1.1}
function playSE(kind,f=null,options={}){if(!sound)return;try{const engine=typeof window!=='undefined'?window.ArenaSound:null;engine?.play(kind,{pan:f?Math.max(-.7,Math.min(.7,(f.x/W-.5)*1.3)):0,character:f?.char||0,...options})}catch{}}
function stopSE(){try{if(typeof window!=='undefined')window.ArenaSound?.stopAll()}catch{}}
function skillSound(f,name){if(f.char===1)return name==='炎の扇'?'fire':name==='熱衝撃'?'thermal':'ice';return ({0:'charge',2:'metal',3:'slash',4:'charge',5:'poison',6:name==='応急処置'?'heal':'slash',7:'charge',8:'shield',9:'skill',10:'air',11:'root',12:'skill',13:name==='無敵'?'shield':'heavy',14:'growth',15:'heavy',16:'slash',17:'malfunction',18:'resin',19:'thunder',20:'charge',21:'ice',22:'heavy',23:'metal',24:'heavy',25:'air'})[f.char]||'skill'}
function impactSound(f,c,type,dot,damage){if(type==='earth')return 'heavy';if(type==='sureHit')return 'heavy';if(type==='pressure'||type==='cyclone')return 'air';if(type==='thermal'&&f.char===38)return 'fire';if(type==='gravity')return damage>=90?'heavy':'air';if(dot)return 'poison';if(type==='grapple')return 'grapple';if(type==='plant')return 'vine-hit';if(type==='crush')return 'heavy';if(type==='explosive')return 'explosion';if(f.char===1)return c==='#edccff'?'thermal':['#ffb478','#ff9364','#ff9761','#ffc79f'].includes(c)?'fire':'ice';return ({0:damage>=90?'heavy':'hit',2:'metal',3:'slash',4:'heavy',5:'poison',6:'slash',7:'explosion',8:'metal',9:'hit',10:'air',11:'vine-hit',12:'explosion',13:'heavy',14:'heavy',15:'heavy',16:'slash',17:'malfunction',18:'resin',19:'thunder',20:damage>=90?'heavy':'air',21:'ice',22:'heavy',23:'metal',24:'heavy',25:'air'})[f.char]||'hit'}

