function reflectDamage(f,source,received){if(!running||!battleAlive(source)||source.overflowQueued||received<=0||avoidDamage(source,false))return;const damage=Math.max(1,Math.round(received*(f.reflectBoost>0?.65:.3)));if(!applyDamageHP(source,damage))return;playSE('reflect',f);f.totalReflected+=damage;f.reflectCharge=Math.min(180,f.reflectCharge+damage);source.hit=.12;fx.push({x:f.x,y:f.y-25,tx:source.x,ty:source.y-25,c:colors[f.id],r:5,kind:'beam',life:.35,max:.35});ring(f.x,f.y-25,colors[f.id],65,'mirror',.45);labels.push({x:source.x,y:source.y-100,text:'反射 −'+damage,c:colors[source.id],life:1});queueOverflow(source);if(!battleAlive(source)&&!source.summon)finish()}
