function tickBombs(dt){for(const b of bombs){withSelfSkill(b.selfSkillOwner,()=>{if(!running)return;b.t+=dt;if(b.t>=b.delay){b.done=true;ring(b.x,b.y-25,'#ffe4b8',45,'impact',.65);ring(b.x,b.y-25,b.c,15,'ring',.65);burst(b.x,b.y-25,b.c,30);playSE('explosion',fighters[b.owner]);for(const target of crowdOverflowTargets(b.owner)){if(!running)return;if(Math.hypot(target.x-b.x,target.y-b.y)<b.r)hit(target,b.damage,fighters[b.owner],b.c)}}});}bombs=bombs.filter(b=>!b.done)}
