function clearMotion(){fighters.forEach(v=>{v.turn=0;v.prevX=v.x;v.prevY=v.y;v.vx=v.vy=0})}
function tickUnstoppable(o){if(o.t>=o.duration){const f=fighters[o.owner];f.invincible=Math.max(f.invincible,5);f.powerBuff=5;playSE('shield',f);f.frozen=0;f.rootTime=0;f.rootOwner=-1;f.rootTick=0;f.bind=0;overflow=null;$('skillcut').classList.remove('overflow');clearMotion();log('俺が相手だ：5秒間・無敵＋攻撃力2倍＋CT回復2倍')}}
function colossusRect(f,o){const scale=bodyScale(f),u=clamp((o.t-.4)/1,0,1),ease=1-Math.pow(1-u,2);return {x:(o.fromX-46*scale)*(1-ease),y:(o.fromY-109*scale)*(1-ease),w:92*scale+(W-92*scale)*ease,h:138*scale+(H-138*scale)*ease}}
