function setJekyllForm(f,hyde,forced=false){if(f.char!==45)return;if(f.jekyllHyde===hyde&&!forced)return;f.jekyllHyde=hyde;f.jekyllSwap=8;f.jekyllToken++;f.dash=null;f.iceDash=null;f.follow=0;f.turn=0;f.jekyllHUDForm=null;if(!forced){ring(f.x,f.y-30,hyde?'#d0b486':'#bfdca6',65,'ring',.6);log(hyde?'ハイド：ここからは俺の時間だ！':'ジキル：ご、ごめんなさい……！')}}
