function jekyllCut(f,e,damage,reach){if(!running||!titanRushCanAct(f)||Math.hypot(e.x-f.x,e.y-f.y)>reach)return false;const landed=hit(e,damage,f,'#d5c390');fx.push({x:e.x,y:e.y-30,c:'#e2dfb7',kind:'shearCut',angle:Math.atan2(e.y-f.y,e.x-f.x),life:.3,max:.3});return landed}
function castJekyll(f,i,e){const token=f.jekyllToken,hyde=f.jekyllHyde,valid=()=>running&&battleAlive(f)&&f.jekyllToken===token&&titanRushCanAct(f);if(!hyde){if(i===1){if(Math.hypot(e.x-f.x,e.y-f.y)<270&&hit(e,65,f,'#bfdca6')){const a=Math.atan2(e.y-f.y,e.x-f.x);e.x=clamp(e.x+Math.cos(a)*150,55,W-55);e.y=clamp(e.y+Math.sin(a)*150,135,H-65)}ring(f.x,f.y-30,'#bfdca6',110,'ring',.6);f.follow=0;f.turn=0;return}const count=i===0?2:3;for(let n=0;n<count;n++)schedule(n*.12,()=>{if(valid())throwJekyllShears(f,attackTarget(f),i===0?36:45,i===2?(n-1)*.22:0)});f.follow=0;f.turn=0;return}
 if(i===0&&!untouchable(e)&&!(e.invincible>0)){const a=Math.atan2(e.y-f.y,e.x-f.x);e.x=clamp(f.x+Math.cos(a)*110,55,W-55);e.y=clamp(f.y+Math.sin(a)*110,135,H-65);ring(e.x,e.y-30,'#d5c390',40,'ring',.35)}
 dash(f,e,60,()=>{if(!valid())return;f.follow=i===2?1.2:.6;const count=[3,2,6][i],damage=[55,110,40][i];for(let n=0;n<count;n++)schedule(n*.11,()=>{if(valid())jekyllCut(f,attackTarget(f),damage,210)})})
}
