function selfSkillActive(owner){return owner!==undefined&&fighters[owner]?.brainwashTime>0}
function skillEnemy(f){return selfSkillContext?.owner===f.id?f:fighters[1-f.id]}
function withSelfSkill(owner,fn){if(!selfSkillActive(owner))return fn();const previous=selfSkillContext,getCollections=()=>[shots,pools,bombs,lightningZones,diamondSoldiers,...fighters.map(f=>f.ripiaZones)],seen=new Set(getCollections().flat());selfSkillContext={owner,hit:false};try{return fn()}finally{for(const collection of getCollections())for(const item of collection)if(!seen.has(item))item.selfSkillOwner=owner;selfSkillContext=previous}}
function cast(f,i){return withSelfSkill(f.brainwashTime>0?f.id:undefined,()=>executeNormalSkill(f,i))}
