function drawMindPulse(e){ring(e.x,e.y-60,'#e2a7bb',65,'cage',.6)}
function menouDebuff(e,f,seal){if(selfSkillContext?.owner===f.id)e=f;if(untouchable(e)||e.invincible>0||e.riftMirror>0)return;e.menouSeal=Math.max(e.menouSeal,seal);e.menouFragile=Math.max(e.menouFragile,3);drawMindPulse(e)}
function castMenou(f,i,e){if(i===0){if(hit(e,65,f,'#d89ba8'))menouDebuff(e,f,1);return}dash(f,e,80,()=>{f.follow=.4;const count=i===1?1:3;for(let n=0;n<count;n++)schedule(n*.14,()=>{if(!running||!titanRushCanAct(f)||Math.hypot(e.x-f.x,e.y-f.y)>190)return;const landed=hit(e,i===1?120:50,f,'#d89ba8');ring(e.x,e.y-30,'#e2a7bb',30,'impact',.35);if(landed&&i===2)menouDebuff(e,f,0)})})}
function castSickness(f,i,e){if(i===0){f.shadowMove=.9;f.skillLock=.9;f.follow=0;f.turn=0;return}if(i===1){if(hit(e,75,f,'#b5afd0')){if(selfSkillContext?.owner===f.id)e=f;e.shadowPin=Math.max(e.shadowPin,1.8);e.dash=null;e.iceDash=null;ring(e.x,e.y+10,'#b5afd0',58,'roots',.6)}return}for(let n=0;n<5;n++)schedule(n*.11,()=>{if(!running||!battleAlive(f))return;projectile(f,attackTarget(f),'blade');Object.assign(shots[shots.length-1],{damage:35,r:10,c:'#b5afd0'})})}
function tickMindShadow(f,dt){for(const key of ['brainwashTime','menouSeal','menouFragile','shadowMove','shadowPin'])f[key]=Math.max(0,(f[key]||0)-dt);if(f.brainwashTime<=0)f.brainwashOwner=-1}
function drawShadowBody(f){ctx.save();ctx.fillStyle='#171424';ctx.strokeStyle='#aaa3cc';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(f.x,f.y+20,55,18,0,0,7);ctx.fill();ctx.stroke();ctx.font='bold 11px sans-serif';ctx.fillStyle='#d8d1ee';ctx.textAlign='center';ctx.fillText('影移動',f.x,f.y-10);ctx.restore()}
function drawMindMark(f,t){if(isConcealed(f))return;ctx.save();ctx.strokeStyle='#e2a7bb';ctx.lineWidth=3;for(let n=0;n<4;n++){ctx.beginPath();ctx.arc(f.x,f.y-75,17+n*10,t+n*.5,t+n*.5+4.8);ctx.stroke()}ctx.restore()}
function drawMindShadow(){for(const f of fighters){if(f.brainwashTime>0||f.menouSeal>0)drawMindMark(f,reduced?0:elapsed*4);if(f.shadowPin>0){ctx.save();ctx.strokeStyle='#b5afd0';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(f.x-45,f.y+26);ctx.lineTo(f.x+45,f.y+26);ctx.moveTo(f.x,f.y-20);ctx.lineTo(f.x,f.y+40);ctx.stroke();ctx.restore()}}}

function ganacheSlash(x,y,c){fx.push({x,y,c,kind:'ganacheSlash',life:.7,max:.7});playSE('slash',fighters.find(f=>f.char===40)||fighters[0])}
function drawGanacheSlash(x,y,c,p){ctx.save();ctx.translate(x,y);ctx.strokeStyle=c;ctx.lineWidth=7*(1-p)+2;ctx.lineCap='round';for(let n=0;n<5;n++){const a=-.9+n*.42,len=80+p*90;ctx.save();ctx.rotate(a);ctx.beginPath();ctx.moveTo(-len,-26+n*12);ctx.lineTo(len,26-n*12);ctx.stroke();ctx.strokeStyle='#fff0fa';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-len*.8,-16+n*8);ctx.lineTo(len*.8,16-n*8);ctx.stroke();ctx.restore()}ctx.restore()}
function nineHit(f,damage,critical=false){if(!running||!battleAlive(f))return false;const e=skillEnemy(f);if(isConcealed(e)||e.shadowMove>0)return false;const landed=hit(e,damage,f,critical?'#ffe1a0':'#f4cc86',0,false,'sureHit');fx.push({x:e.x,y:e.y-30,c:'#ffe1a0',critical,kind:'nineImpact',life:critical?.8:.35,max:critical?.8:.35});return landed}
function throwNine(f,damage){const e=skillEnemy(f);fx.push({x:f.x,y:f.y-25,owner:f.id,target:e.id,c:'#fff1db',kind:'ninePitch',life:.3,max:.3});playSE('shoot-blade',f);schedule(.28,()=>{if(running&&battleAlive(f))nineHit(f,damage)})}
function castNine(f,i){const enemy=skillEnemy(f),e=isConcealed(enemy)?attackTarget(f):enemy;if(i===0){throwNine(f,160);return}dash(f,e,60,()=>{f.follow=.4;const count=i===1?1:7;for(let n=0;n<count;n++)schedule(n*.11,()=>{if(titanRushCanAct(f))nineHit(f,i===1?220:42)})})}
function drawNinePitch(q,p){const e=fighters[q.target];if(!e||isConcealed(e))return;const x=q.x+(e.x-q.x)*p,y=q.y+(e.y-25-q.y)*p-Math.sin(p*Math.PI)*50;ctx.strokeStyle='#ffe1a0';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.quadraticCurveTo((q.x+x)/2,y-35,x,y);ctx.stroke();ctx.fillStyle='#fff4e6';ctx.beginPath();ctx.arc(x,y,11,0,7);ctx.fill();ctx.strokeStyle='#e45c65';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,7,-1.2,1.2);ctx.stroke()}
function drawNineImpact(x,y,c,p,critical){ctx.save();ctx.translate(x,y);ctx.strokeStyle=c;ctx.lineWidth=critical?5:3;const size=(critical?130:45)*(1+p);for(let n=0;n<(critical?12:6);n++){const a=n*Math.PI/(critical?6:3);ctx.beginPath();ctx.moveTo(Math.cos(a)*size*.3,Math.sin(a)*size*.3);ctx.lineTo(Math.cos(a)*size,Math.sin(a)*size);ctx.stroke()}ctx.fillStyle='#fff4d4';ctx.font='bold '+(critical?22:12)+'px sans-serif';ctx.textAlign='center';ctx.fillText(critical?'超クリティカル':'必中',0,-size*.6);ctx.restore()}
function ripiaZone(f,x,y,delay=.45,r=125,damage=90,roots=false){f.ripiaZones.push({x:clamp(x,55,W-55),y:clamp(y,135,H-65),left:delay,max:delay,r,damage,roots})}
function castRipia(f,i,e){if(i===0){const landed=hit(e,90,f,'#bad99a',0,false,'plant');if(landed)applyRoots(e,f,1.6);return}if(i===1){const x=e.x+(e.mx||0)*.15,y=e.y+(e.my||0)*.15;for(let n=-1;n<=1;n++)ripiaZone(f,x+n*85,y+n*35,.4+(n+1)*.15,115,100);return}for(let n=0;n<2;n++)schedule(n*.3,()=>{if(!running||!battleAlive(f)||!titanRushCanAct(f))return;shake=reduced?0:7;for(const target of pressureTargets(f)){hit(target,95,f,'#bad99a',.3,false,'earth');if(!running)break}fx.push({x:W/2,y:H/2,r:330,c:'#bad99a',kind:'earthBurst',life:.6,max:.6})})}
function tickRipia(f,dt){if(f.char!==42)return;if(f.ripiaField>0){f.ripiaField=Math.max(0,f.ripiaField-dt);f.ripiaPulse-=dt;f.ripiaSpawn-=dt;if(f.ripiaPulse<=0){f.ripiaPulse+=.6;for(const e of pressureTargets(f)){hit(e,38,f,'#bad99a',0,false,'earth');if(!running)return}}if(f.ripiaSpawn<=0){f.ripiaSpawn+=.55;for(const e of pressureTargets(f))ripiaZone(f,e.x+(e.mx||0)*.13,e.y+(e.my||0)*.13,.4,125,80,true)}}for(const z of f.ripiaZones){withSelfSkill(z.selfSkillOwner,()=>{z.left-=dt;if(z.left<=0){z.done=true;fx.push({x:z.x,y:z.y-20,r:z.r,c:'#bad99a',kind:'earthBurst',life:.6,max:.6});playSE('explosion',f);for(const e of pressureTargets(f)){if(Math.hypot(e.x-z.x,e.y-z.y)<z.r+hurtRadius(e)){const landed=hit(e,z.damage,f,'#bad99a',0,false,'earth');if(landed&&z.roots)applyRoots(e,f,.7)}if(!running)return}}});}f.ripiaZones=f.ripiaZones.filter(z=>!z.done)}
function drawEarthBurst(x,y,r,p){ctx.save();ctx.strokeStyle='#bfe49c';ctx.fillStyle='#776759';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(x,y,r*(.3+p*.8),r*(.15+p*.3),0,0,7);ctx.stroke();for(let n=0;n<9;n++){const a=n*2.4,dist=r*(.25+n*.06),px=x+Math.cos(a)*dist,py=y+Math.sin(a)*dist*.35-(1-p)*70;ctx.beginPath();ctx.moveTo(px-11,py+16);ctx.lineTo(px-4,py-20);ctx.lineTo(px+15,py-6);ctx.lineTo(px+10,py+18);ctx.closePath();ctx.fill();ctx.stroke()}ctx.restore()}
function drawLivingEarth(f,t){ctx.save();ctx.fillStyle='#719254';ctx.globalAlpha=.12;ctx.fillRect(24,75,W-48,H-100);ctx.globalAlpha=.6;ctx.strokeStyle='#bfe49c';ctx.lineWidth=3;for(let n=0;n<9;n++){const x=40+n*70;ctx.beginPath();ctx.moveTo(x,H-30);ctx.bezierCurveTo(x+Math.sin(t*3+n)*35,H-150,x-25,140,x+Math.cos(t*2+n)*40,80);ctx.stroke()}ctx.restore()}
function drawRipiaField(){for(const f of fighters){if(f.char!==42)continue;if(f.ripiaField>0)drawLivingEarth(f,reduced?0:elapsed);for(const z of f.ripiaZones){ctx.save();ctx.strokeStyle='#ddf7ae';ctx.fillStyle='#a1c778';ctx.globalAlpha=.14;ctx.beginPath();ctx.ellipse(z.x,z.y-10,z.r,z.r*.55,0,0,7);ctx.fill();ctx.globalAlpha=.8;ctx.lineWidth=2;ctx.setLineDash([7,6]);ctx.stroke();ctx.setLineDash([]);ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.fillStyle='#def5be';ctx.fillText('地面噴出 '+Math.max(0,z.left).toFixed(1),z.x,z.y);ctx.restore()}}}

function ganacheKick(f,e,damage,reach){if(!running||!titanRushCanAct(f)||Math.hypot(e.x-f.x,e.y-f.y)>reach)return false;const before=e.hp,landed=hit(e,damage,f,'#e7add2');if(running&&landed&&!e.summon&&e===fighters[1-f.id])f.ganacheWounds+=Math.max(0,before-e.hp);fx.push({x:f.x,y:f.y-25,tx:e.x,ty:e.y-30,angle:Math.atan2(e.y-f.y,e.x-f.x),c:'#f5b5d8',r:75,kind:'ganacheKick',life:.3,max:.3});return landed}
function castGanache(f,i,e){if(i===2){const enemy=fighters[1-f.id],damage=Math.min(450,100+f.ganacheWounds*.35);hit(enemy,damage,f,'#e7add2',0,false,'erosion');ring(enemy.x,enemy.y-30,'#e7add2',75,'cage',.7);return}dash(f,e,65,()=>{f.follow=.5;const count=i===0?3:2;for(let n=0;n<count;n++)schedule(n*.14,()=>ganacheKick(f,attackTarget(f),i===0?65:110,i===0?180:205))})}
function drawGanacheKick(q,progress){ctx.save();ctx.translate(q.x,q.y);ctx.rotate(q.angle);ctx.strokeStyle=q.c;ctx.lineWidth=5;ctx.beginPath();ctx.arc(15,0,q.r,-1+progress*.8,1.1+progress*.8);ctx.stroke();ctx.strokeStyle='#fff0fa';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,10);ctx.lineTo(75,-22);ctx.lineTo(105,10);ctx.stroke();ctx.restore()}

function tickDreamFlame(f,dt){if(!(f.dreamFlameTime>0))return;if(!titanRushCanAct(f)){f.dreamFlameTime=0;return}f.dreamFlameTime=Math.max(0,f.dreamFlameTime-dt);f.dreamFlameTick-=dt;if(f.dreamFlameTick<=0){f.dreamFlameTick+=.2;for(const e of pressureTargets(f)){const dx=e.x-f.x,dy=e.y-f.y,d=Math.hypot(dx,dy),angle=Math.atan2(dy,dx)-f.dreamFlameAngle,delta=Math.atan2(Math.sin(angle),Math.cos(angle));if(d<430+hurtRadius(e)&&Math.abs(delta)<.9){const landed=hit(e,55*(e.drunk>0?1.5:1),f,'#ff9955',0,false,'thermal');if(landed&&battleAlive(e)){e.burn=Math.max(e.burn,3);e.burnTick=.75}if(!running)break}}}}
function drawDreamFlame(f){ctx.save();ctx.translate(f.x,f.y-22);ctx.rotate(f.dreamFlameAngle);const flicker=reduced?0:Math.sin(elapsed*38)*12;for(let n=0;n<3;n++){const r=430-n*55+flicker,angle=.9-n*.14;ctx.fillStyle=['#ff602833','#ff943f66','#ffe08d99'][n];ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,r,-angle,angle);ctx.closePath();ctx.fill()}ctx.strokeStyle='#ffd993';ctx.lineWidth=3;for(let n=0;n<9;n++){const a=-.8+n*.2,r=90+((elapsed*650+n*47)%330);ctx.beginPath();ctx.arc(Math.cos(a)*r,Math.sin(a)*r,8+(n%3)*5,a-1,a+1);ctx.stroke()}ctx.restore()}
function rangedSpacingPoint(f,e,spacing=300){const away=Math.atan2(f.y-e.y,f.x-e.x),side=(f.route+f.id)%2?1:-1;let best=null,bestScore=-Infinity;for(const radius of [spacing,spacing*.8,spacing*.6])for(const offset of [side*.6,-side*.6,side*1.2,-side*1.2,side*1.8,-side*1.8,Math.PI,0]){const a=away+offset,x=e.x+Math.cos(a)*radius,y=e.y+Math.sin(a)*radius;if(x<105||x>W-105||y<185||y>H-110)continue;const clearance=Math.min(x-55,W-55-x,y-135,H-65-y),travel=Math.hypot(x-f.x,y-f.y);const score=-Math.abs(radius-spacing)*.35+Math.min(100,clearance)*.6+(Math.sign(offset)===side?8:0)-Math.abs(Math.abs(offset)-1.2)*8+(travel>100?10:0);if(score>bestScore){bestScore=score;best={x,y}}}return best||{x:W/2,y:415}}

function accuracyMiss(f,type,dot){if(!f||dot||['judgment','pressure','cyclone','sureHit','field','grapple'].includes(type))return false;const chance=f.bloodRush>0?.55:f.drunk>0?.38:0;if(chance&&Math.random()<chance){ring(f.x,f.y-30,'#f4c582',16,'ring',.2);return true}return false}
function applyDrunk(f,time){if(f.summon||untouchable(f)||f.invincible>0||f.riftMirror>0)return;f.drunk=Math.max(f.drunk,Math.min(1.5,time));if(f.drunkGap<=0){f.drunkStumble=.16;f.drunkGap=1.1;f.drunkAngle=Math.atan2(f.my||0,f.mx||1)+(Math.random()-.5)*.9;f.dash=null;f.iceDash=null;}ring(f.x,f.y-70,'#f4c582',30,'ring',.5)}
function moveDrunk(f,dt){const v=470*roster[f.char].speed*motorRate(f)*(f.slow>0?.65:1)*(f.bind>0?.3:1)*(f.windup>0?.35:1);f.mx=Math.cos(f.drunkAngle)*v;f.my=Math.sin(f.drunkAngle)*v;f.x+=(f.mx+f.vx)*dt;f.y+=(f.my+f.vy)*dt}
function dreamShot(f,e,damage,offset=0,time=3){projectile(f,e,'alcohol',offset);Object.assign(shots[shots.length-1],{damage,r:12,c:'#f4c582',drunkDuration:time})}
function windShot(f,e,damage,offset=0){projectile(f,e,'tornado',offset);Object.assign(shots[shots.length-1],{damage,r:26,c:'#b9e2df'});shots[shots.length-1].vx*=.8;shots[shots.length-1].vy*=.8}
function castDream(f,i,e){if(i===2){f.dreamFlameSelfSkillOwner=selfSkillContext?.owner;f.dreamFlameTime=1.2;f.dreamFlameTick=0;f.dreamFlameAngle=Math.atan2(e.y-f.y,e.x-f.x);f.skillLock=1.2;f.windup=1.2;playSE('fire',f);return}const count=[3,10,6][i];for(let n=0;n<count;n++)schedule(n*(i===1?.045:.13),()=>{if(!running||!battleAlive(f))return;dreamShot(f,attackTarget(f),[42,32,50][i],i===1?(n%5-2)*.19:0,i===2?4:3)})}
function pressureTargets(f){if(selfSkillContext?.owner===f.id)return [f];return [fighters[1-f.id],...diamondSoldiers.filter(v=>v.owner!==f.id&&battleAlive(v))]}
function applyPressure(f,e,time){if(e.summon){hit(e,45,f,'#b9e2df',0,true,'pressure');return}if(untouchable(e)||e.invincible>0||e.riftMirror>0)return;e.pressureTime=Math.max(e.pressureTime,time);e.pressureOwner=f.id;e.pressureTick=0;ring(e.x,e.y-35,'#b9e2df',65,'ring',.6)}
function castMatsumaro(f,i,e){if(i===0)applyPressure(f,skillEnemy(f),4);else if(i===1){for(let n=-1;n<=1;n++)windShot(f,e,100,n*.22)}else for(const target of pressureTargets(f)){hit(target,85,f,'#b9e2df',0,true,'pressure');if(running)applyPressure(f,target,5)}}
function tickDreamWeather(f,dt){withSelfSkill(f.dreamFlameSelfSkillOwner,()=>tickDreamFlame(f,dt));if(!running)return;f.drunk=Math.max(0,(f.drunk||0)-dt);f.drunkStumble=Math.max(0,(f.drunkStumble||0)-dt);f.drunkGap=Math.max(0,(f.drunkGap||0)-dt);if(f.bloodRush>0){f.bloodRush=Math.max(0,f.bloodRush-dt);if(f.bloodRush<=0){f.maxHp=roster[f.char].maxHp||MAX_HP;f.hp=Math.min(f.hp,f.maxHp)}}if(f.pressureTime>0){f.pressureTime=Math.max(0,f.pressureTime-dt);f.pressureTick-=dt;if(f.pressureTick<=0){f.pressureTick+=.5;const owner=fighters[f.pressureOwner];if(owner&&battleAlive(owner))hit(f,30,owner,'#b9e2df',0,true,'pressure')}}if(!running)return;if(f.cycloneTime>0){f.cycloneTime=Math.max(0,f.cycloneTime-dt);f.cycloneTick-=dt;if(f.cycloneTick<=0){f.cycloneTick+=.3;for(const e of pressureTargets(f)){hit(e,45,f,'#b9e2df',0,true,'cyclone');if(!running)break}}}}
function drawCyclone(x,y,r,t,c){ctx.save();ctx.strokeStyle=c;ctx.lineWidth=3;for(let n=0;n<9;n++){const h=n*r*.3,rr=r*(.25+n*.13);ctx.globalAlpha=.3+n*.06;ctx.beginPath();ctx.ellipse(x+Math.sin(t+n*.55)*r*.15,y-h,rr,rr*.25,Math.sin(t+n)*.15,t+n*.6,t+n*.6+5.3);ctx.stroke()}ctx.restore()}
function drawWeather(){for(const f of fighters){if(f.dreamFlameTime>0)drawDreamFlame(f);if(f.cycloneTime>0){drawCyclone(W/2,H-45,240,reduced?0:elapsed*7,'#b9e2df')}if(f.pressureTime>0){ctx.save();ctx.strokeStyle='#b9e2df';ctx.lineWidth=2;for(let n=0;n<4;n++){ctx.beginPath();ctx.ellipse(f.x,f.y-20-n*28,58,16,0,0,7);ctx.stroke()}ctx.restore()}if(f.drunk>0||f.bloodRush>0){ctx.save();ctx.strokeStyle='#f4c582';ctx.lineWidth=f.bloodRush>0?4:2;ctx.beginPath();ctx.ellipse(f.x,f.y-35,f.bloodRush>0?62:45,75,Math.sin(elapsed*4)*.15,0,7);ctx.stroke();ctx.restore()}}}

function castDarkness(f,i,target){
 if(i===0){dash(f,target,DARKNESS_SPACING.clawStop,()=>{f.follow=0;for(let n=0;n<5;n++)schedule(n*.12,()=>darkClaw(f,target,30,260))})}
 else if(i===1){f.darkArmor=3.5;ring(f.x,f.y-25,'#a996b4',82,'shield',.6);for(const victim of crowdOverflowTargets(f.id)){if(Math.hypot(victim.x-f.x,victim.y-f.y)<240&&hit(victim,58,f,'#b4d991'))applyPoison(victim,f,2)}}
 else darkFeathers(f,target);
}
function tickDarkness(f,dt){
 if(f.char!==37||f.summon||!running)return;
 f.darkArmor=Math.max(0,f.darkArmor-dt);
 if(f.darkStand>0){f.darkStand=Math.max(0,f.darkStand-dt);f.hp=0;f.darkCutCd-=dt;f.darkFeatherCd-=dt;if(f.darkStand<=1e-9){f.ganacheOFTriggered=false;f.ganacheWounds=0;f.drunkStumble=0;f.drunkGap=0;f.dreamFlameTime=0;f.dreamFlameTick=0;f.dreamFlameAngle=0;f.drunk=0;f.drunkTurn=0;f.drunkAngle=0;f.bloodRush=0;f.pressureTime=0;f.pressureTick=0;f.pressureOwner=-1;f.cycloneTime=0;f.cycloneTick=0;f.darkStand=0;finish();return}}
 else if(f.hp>0&&!overflow)restoreHP(f,18*dt);
 f.healDisplayClock-=dt;if(f.healDisplayClock<=0&&f.healBank>=1){labels.push({x:f.x,y:f.y-105,text:'+'+Math.round(f.healBank),c:'#c9e7d3',life:.7});f.healBank=0;f.healDisplayClock=.7}
}
function prepareDarkRush(f,target){
 if(f.char!==37||!(f.darkStand>0)||!titanRushCanAct(f))return;
 f.follow=0;if(!f.dash&&Math.hypot(target.x-f.x,target.y-f.y)>260)dash(f,target,DARKNESS_SPACING.overflowStop);
}
function darkRushHits(){
 for(const f of fighters){if(!running)break;if(f.char!==37||!(f.darkStand>0)||!titanRushCanAct(f))continue;const target=attackTarget(f);
 if(f.darkCutCd<=0&&Math.hypot(target.x-f.x,target.y-f.y)<270){f.darkCutCd=.14;darkClaw(f,target,36,270)}
 if(f.darkFeatherCd<=0){f.darkFeatherCd=.5;darkFeathers(f,target,3,25)}}
}
function drawDarknessBody(f){
 ctx.save();if(f.darkStand>0){const flap=Math.sin(elapsed*(reduced?3:16))*9;
 for(const side of [-1,1]){ctx.save();ctx.scale(side,1);ctx.fillStyle=side<0?'#252132':'#f3f0fa';ctx.strokeStyle=side<0?'#b1a3c9':'#cbbfe2';ctx.lineWidth=2;
 ctx.beginPath();ctx.moveTo(9,-45);ctx.bezierCurveTo(36,-120-flap,100,-130-flap,124,-103-flap);ctx.quadraticCurveTo(73,-88,67,-14);ctx.lineTo(25,5);ctx.closePath();ctx.fill();ctx.stroke();
 for(let n=0;n<7;n++){const x=43+n*11,y=-83+Math.sin(n*.45)*-16-flap;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x+20,y+28,x+8,y+65-n*3);ctx.quadraticCurveTo(x-9,y+26,x-9,y+10);ctx.fill();ctx.stroke()}ctx.restore()}
 ctx.fillStyle='#eadfff';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText('不死の五秒 '+f.darkStand.toFixed(1)+'s',0,-142);
 }if(f.darkArmor>0){ctx.strokeStyle='#b2a0bf';ctx.fillStyle='#5a4b6844';ctx.lineWidth=4;ctx.beginPath();for(let n=0;n<6;n++){const a=n*Math.PI/3;ctx.lineTo(Math.cos(a)*51,Math.sin(a)*60-28)}ctx.closePath();ctx.fill();ctx.stroke()}ctx.restore();
}

function serenaKnifeHit(f,target,damage,reach){
 if(!running||!battleAlive(f)||!titanRushCanAct(f)||Math.hypot(target.x-f.x,target.y-f.y)>=reach)return false;
 const before=target.hp,landed=hit(target,damage,f,colors[f.id]);
 const dealt=Math.max(0,before-target.hp);
 if(landed&&dealt>0){restoreHP(f,Math.min(70,dealt*(f.serenaRush>0?.35:.25)+(f.serenaRush>0?16:11)));ring(target.x,target.y-30,'#d8fff1',18,'slash',.22)}
 fx.push({x:target.x,y:target.y-30,angle:Math.atan2(target.y-f.y,target.x-f.x)+(Math.floor(elapsed*12)%2?.65:-.65),r:f.serenaRush>0?36:28,rush:f.serenaRush>0,c:landed?'#dbfff0':colors[f.id],kind:'serenaCut',life:.22,max:.22});f.attack=.18;return landed;
}
function castSerenaKnife(f,i,target){
 const count=[4,3,6][i],damage=[30,60,40][i],reach=i===1?140:135;
 f.skillLock=i===2?1.2:.8;
 let started=false;const cut=()=>{if(started)return;started=true;for(let n=0;n<count;n++)schedule(n*(i===2?.09:.12),()=>serenaKnifeHit(f,target,damage,reach))};
 dash(f,target,-85,()=>{f.follow=0;cut()});if(f.dash)f.dash.serenaCut=cut;
}
function tickSerenaState(f,dt){
 if(f.char!==36||!running||!battleAlive(f))return;
 const active=Math.min(f.serenaRush,dt);f.serenaRush=Math.max(0,f.serenaRush-dt);f.serenaCutCd-=dt;
 if(active>0)restoreHP(f,90*active);
 f.healDisplayClock-=dt;
 if(f.healDisplayClock<=0&&f.healBank>=1){labels.push({x:f.x,y:f.y-105,text:'+'+Math.round(f.healBank),c:'#b5ffe4',life:.6});f.healBank=0;f.healDisplayClock=.4;fx.push({x:f.x,y:f.y-25,c:'#b5ffe4',kind:'serenaHeal',life:.42,max:.42})}
}
function prepareSerenaRush(f,target){
 if(f.char!==36||!(f.serenaRush>0)||!titanRushCanAct(f)||manualMode&&f.id===0)return;
 f.follow=0;f.sprint=Math.max(f.sprint,.2);
}
function serenaRushHits(){
 for(const f of fighters){if(!running)break;if(f.char!==36||!(f.serenaRush>0)||f.serenaCutCd>0||!titanRushCanAct(f))continue;
 const target=attackTarget(f);if(Math.hypot(target.x-f.x,target.y-f.y)<135){f.serenaCutCd=.13;serenaKnifeHit(f,target,24,135)}}
}
function drawSerenaAura(f){
 const rushing=f.serenaRush>0,moving=Math.hypot(f.mx||0,f.my||0)>280;
 ctx.save();ctx.strokeStyle='#c9ffe6';ctx.lineCap='round';
 if(moving&&!reduced){const angle=Math.atan2(f.my,f.mx);ctx.save();ctx.rotate(angle);ctx.globalAlpha=rushing?.45:.25;ctx.lineWidth=rushing?3:2;
  for(let n=-1;n<=1;n++){const length=(rushing?62:38)+(n+1)*7;ctx.beginPath();ctx.moveTo(-25,-28+n*14);ctx.lineTo(-25-length,-28+n*14);ctx.stroke()}ctx.restore()}
 if(rushing){ctx.shadowColor='#b5ffe4';ctx.shadowBlur=reduced?0:12;ctx.globalAlpha=.55;ctx.lineWidth=2;
  for(let n=0;n<3;n++){ctx.beginPath();ctx.ellipse(0,-25,43+n*8,58+n*6,elapsed*(reduced?2:12)+n,0,Math.PI*1.35);ctx.stroke()}
  ctx.globalAlpha=.7;ctx.beginPath();ctx.ellipse(0,29,51+Math.sin(elapsed*8)*3,17,0,0,7);ctx.stroke();ctx.shadowBlur=0;ctx.globalAlpha=1;ctx.fillStyle='#d1ffe5';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText('集中治療 '+f.serenaRush.toFixed(1)+'s',0,-128)}ctx.restore();
}
function drawSerenaEffect(q,progress){
 ctx.save();ctx.translate(q.x,q.y);ctx.strokeStyle=q.c;ctx.lineCap='round';
 if(q.kind==='shearCut'){drawShearCut(q,progress)}else if(q.kind==='ganacheSlash'){drawGanacheSlash(q.x,q.y,q.c,progress)}else if(q.kind==='ninePitch'){drawNinePitch(q,progress)}else if(q.kind==='nineImpact'){drawNineImpact(q.x,q.y,q.c,progress,q.critical)}else if(q.kind==='earthBurst'){drawEarthBurst(q.x,q.y,q.r,progress)}else if(q.kind==='ganacheKick'){drawGanacheKick(q,progress)}else if(q.kind==='serenaCut'){
  ctx.rotate(q.angle);ctx.scale(1,.55);const radius=q.r+progress*24;
  for(let n=0;n<(reduced?1:q.rush?3:2);n++){ctx.lineWidth=n?2:4;ctx.globalAlpha*=n?.6:1;ctx.beginPath();ctx.arc(0,0,radius+n*9,-1.3+progress*.8,1.15+progress*.8);ctx.stroke()}
  ctx.strokeStyle='#f0fff9';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-radius*.65,-radius*.5);ctx.lineTo(radius*.65,radius*.5);ctx.stroke();
 }else{
  ctx.lineWidth=2;ctx.globalAlpha*=.7;ctx.beginPath();ctx.ellipse(0,16,32+progress*26,12+progress*5,0,0,7);ctx.stroke();
  for(let n=0;n<(reduced?2:5);n++){const angle=n*2.4,x=Math.cos(angle)*27,y=8-n*12-progress*26;ctx.lineWidth=n%2?2:3;ctx.beginPath();ctx.moveTo(x-4,y);ctx.lineTo(x+4,y);ctx.moveTo(x,y-4);ctx.lineTo(x,y+4);ctx.stroke()}
 }ctx.restore();
}

function fireBodyGun(f,target,form,damage,offset=0,normal=false){
 if(!running||!battleAlive(f))return;
 projectile(f,target,form===2?'explosive':'gun',offset);
 const shot=shots[shots.length-1],velocity=form===2?940:form===1?1080:1250;
 Object.assign(shot,{damage,r:form===2?17:form===1?9:6,c:form===2?'#ffce85':'#f4e3aa',life:1.6});
 const length=Math.hypot(shot.vx,shot.vy)||1;shot.vx*=velocity/length;shot.vy*=velocity/length;
 if(form===2){shot.blastRadius=155;shot.bodyCannon=true}
 if(!normal||!(f.gunTime>0)){f.gunForm=form;f.gunTime=Math.max(f.gunTime||0,form===2?.7:.25);f.gunAngle=Math.atan2(shot.vy,shot.vx)}f.attack=.2;
 ring(f.x+Math.cos(f.gunAngle)*52,f.y-22+Math.sin(f.gunAngle)*52,'#ffe6a1',form===2?34:12,'impact',.18);
 if(form===2){shake=reduced?0:12;playSE('shoot-bomb',f)}else playSE('shoot-blade',f);
}
function castBodyGun(f,i,target){
 f.gunForm=i;f.gunTime=i===0?1.7:i===1?.9:1.5;f.gunAngle=Math.atan2(target.y-f.y,target.x-f.x);
 f.skillLock=i===0?1.7:1.3;f.windup=i===2?.8:.35;
 if(i===0)for(let n=0;n<10;n++)schedule(.35+n*.11,()=>fireBodyGun(f,attackTarget(f),0,30,(n%3-1)*.018));
 else if(i===1)schedule(.35,()=>{const aim=attackTarget(f);for(let n=-3;n<=3;n++)fireBodyGun(f,aim,1,50,n*.09)});
 else{ring(f.x,f.y-22,colors[f.id],65,'charge',.8);schedule(.8,()=>fireBodyGun(f,attackTarget(f),2,450))}
}
function drawBodyGun(f){
 ctx.save();ctx.translate(0,-24);ctx.rotate(f.gunAngle||0);ctx.strokeStyle='#d7dfc4';ctx.lineWidth=2;ctx.fillStyle='#414d4c';
 // Metal grows from the torso/arm into three distinct barrel silhouettes.
 ctx.beginPath();ctx.moveTo(-18,-14);ctx.lineTo(22,-18);ctx.lineTo(32,-10);ctx.lineTo(32,10);ctx.lineTo(22,18);ctx.lineTo(-18,14);ctx.closePath();ctx.fill();ctx.stroke();
 if(f.gunForm===0){for(let n=-1;n<=1;n++){ctx.fillRect(17,n*7-2,48,4);ctx.strokeRect(17,n*7-2,48,4)}ctx.fillStyle='#727c6c';ctx.fillRect(9,9,20,15)}
 else if(f.gunForm===1){for(let n=-1;n<=1;n+=2){ctx.fillRect(20,n*6-4,42,8);ctx.strokeRect(20,n*6-4,42,8)}ctx.fillStyle='#82906e';ctx.fillRect(25,-12,8,24)}
 else{ctx.fillRect(9,-18,53,36);ctx.strokeRect(9,-18,53,36);ctx.fillStyle='#222e31';ctx.fillRect(53,-21,16,42);ctx.strokeRect(53,-21,16,42);ctx.fillStyle='#ffcf8a';ctx.fillRect(65,-13,4,26)}
 ctx.restore();ctx.fillStyle='#e0e9b5';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText(['機関銃','散弾砲','重砲'][f.gunForm],0,-127);
}

function explosiveBullet(f,e,damage=10,offset=0){projectile(f,e,'explosive',offset);const shot=shots[shots.length-1];shot.c=colors[f.id];shot.damage=damage;shot.r=9;shot.vx*=1.35;shot.vy*=1.35;shot.blastRadius=90;shot.life=1.2}
function explodeBullet(s,e){if(s.exploded)return;s.exploded=true;playSE('explosion',fighters[s.owner]);ring(s.x,s.y,s.c,8,'ring',.28);ring(s.x,s.y,'#ffe8c4',12,'impact',.25);burst(s.x,s.y,s.c,7);if(s.bodyCannon)ring(s.x,s.y,s.c,s.blastRadius,'impact',.55);for(const victim of s.bodyCannon?crowdOverflowTargets(s.owner):[e]){if(!running)break;if(Math.hypot(victim.x-s.x,victim.y-20-s.y)<s.blastRadius+hurtRadius(victim))hit(victim,s.damage,fighters[s.owner],s.c,0,false,'explosive')}s.life=0}
function tickSprout(o,dt){const f=fighters[o.owner];if(o.t>=1&&!o.blast){o.blast=true;f.sprouted=true;f.defense=roster[f.char].defense*2;restoreHP(f,f.maxHp,true);f.rootTime=0;f.rootOwner=-1;f.rootTick=0;ring(f.x,f.y-20,o.color,70,'roots',1.2);burst(f.x,f.y-25,o.color,45);log('芽生え：全回復・攻撃と吸収2倍・被ダメージ2倍')}if(o.t>=o.duration||!running){overflow=null;$('skillcut').classList.remove('overflow');fighters.forEach(v=>{v.turn=0;v.vx=v.vy=0;v.prevX=v.x;v.prevY=v.y})}}

function isSilenced(f){return !!arenaField&&arenaField.owner!==f.id&&!untouchable(f)}
function queueOverflow(f,requested=false){if(f.summon||f.char===37)return;checkPasterForm(f);if(f.char===45)checkJekyllEmergency(f);if(f.char===40&&running&&battleAlive(f)&&!f.overflowUsed){const e=fighters[1-f.id];if(battleAlive(e)&&e.hp<=e.maxHp*.25)f.ganacheOFTriggered=true;}if(manualMode&&f.id===0&&!requested&&![11,30,40,45].includes(f.char))return;if(running&&battleAlive(f)&&overflowReady(f)&&roster[f.char].overflow&&([11,30,40,45].includes(f.char)||!(f.petrified>0)&&!isSilenced(f))&&!f.overflowUsed&&!f.overflowQueued){f.overflowQueued=true;overflowQueue.push(f.id)}}
function startRepulsionField(owner){const enemy=fighters[1-owner];enemy.overflowQueued=false;overflowQueue=overflowQueue.filter(id=>id!==enemy.id);events=[];arenaField={owner,left:5,tick:.06,t:0,pulses:0};fighters.forEach(f=>{f.fieldDamageBank=0;f.fieldLabelClock=0});playSE('air',fighters[owner]);log('俺の間合い：5秒間・相手の技を封印');}
function flushFieldDamage(f){if(f.fieldDamageBank>0){labels.push({x:f.x,y:f.y-100,text:'連続 −'+f.fieldDamageBank,c:colors[f.id],life:.65});f.fieldDamageBank=0;burst(f.x,f.y-25,'#90cbed',4)}}
function tickRepulsionField(dt){const field=arenaField;if(!field||!running)return;const active=Math.min(field.left,dt);field.left=Math.max(0,field.left-dt);field.t+=active;field.tick-=active;const target=fighters[1-field.owner];while(field.tick<=1e-9&&running){field.tick+=.06;field.pulses++;hit(target,8,fighters[field.owner],'#90cbed',0,false,'field')}target.fieldLabelClock-=active;if(target.fieldLabelClock<=0){flushFieldDamage(target);target.fieldLabelClock=.3}if(field.left<=0||!running){flushFieldDamage(target);arenaField=null;fighters.forEach(queueOverflow);if(running)log('俺の間合いが解除された。')}}
function drawRepulsionField(){if(!arenaField)return;const f=arenaField;ctx.save();ctx.fillStyle='#67c7ff';ctx.globalAlpha=.07;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#a1dfff';ctx.lineWidth=1.5;for(let n=0;n<11;n++){const y=65+(n*67+f.t*160)%650;ctx.globalAlpha=.12+(n%3)*.06;ctx.beginPath();ctx.moveTo(25,y);ctx.lineTo(W-25,y-30);ctx.stroke()}for(let n=0;n<7;n++){ctx.globalAlpha=.25;ctx.beginPath();ctx.arc(W/2,H/2,30+(n*80+f.t*240)%550,0,7);ctx.stroke()}ctx.globalAlpha=1;ctx.fillStyle='#c1ecff';ctx.font='bold 15px sans-serif';ctx.textAlign='center';ctx.fillText('俺の間合い · P'+(f.owner+1)+' / 技封印 '+f.left.toFixed(1)+'s',W/2,90);ctx.restore()}

function evasionRate(f){return f.char===9?Math.min(.75,.1+(f.evasionBuffs[0]>0?.25:0)+(f.evasionBuffs[1]>0?.4:0)):0}
function avoidDamage(f,canEvade=true){if(untouchable(f))return true;const immune=f.invincible>0;if(!immune&&(!canEvade||evasionRate(f)<=0||Math.random()>=evasionRate(f)))return false;playSE(immune?'immune':'dodge',f);labels.push({x:f.x,y:f.y-105,text:immune?'無敵':'回避',c:'#ffd0e3',life:.65});ring(f.x,f.y-30,'#f1aac5',45,'ring',.3);return true}
function releaseGrip(f){if(f.grapple){const e=fighters[f.grapple.target];if(e&&e.grabbedBy===f.id){e.grabbedBy=-1;e.turn=0}f.grapple=null;f.turn=0}}
function beginGrip(f,e){if(untouchable(e))return false;if(e.summon)return false;if(e.phantom||!running||!battleAlive(f)||!battleAlive(e)||f.grabbedBy>=0)return false;if(avoidDamage(e))return false;releaseGrip(e);releaseGrip(f);f.dash=null;e.dash=null;f.grapple={target:e.id,left:2.6,tick:.15};e.grabbedBy=f.id;f.mx=f.my=f.vx=f.vy=0;e.mx=e.my=e.vx=e.vy=0;log(nameOf(f)+'：首絞めで拘束');return true}
function tickGrips(dt){for(const f of fighters){const g=f.grapple;if(!g)continue;const e=fighters[g.target];if(!running||!battleAlive(f)||!battleAlive(e)||f.frozen>0){releaseGrip(f);continue}g.left-=dt;g.tick-=dt;f.x=clamp(e.x-52,55,W-55);f.y=clamp(e.y+8,135,H-65);while(g.tick<=0&&g.left>=0&&running){g.tick+=.3;hit(e,28.5,f,colors[f.id],0,false,'grapple');ring(e.x,e.y-75,colors[f.id],14,'grip',.3)}if(g.left<=0||!running)releaseGrip(f)}}
function drawGrip(f,e,color){ctx.save();ctx.strokeStyle=color;ctx.lineWidth=6;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(f.x+15,f.y-62);ctx.quadraticCurveTo(f.x+35,f.y-88,e.x,e.y-76);ctx.stroke();ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(e.x,e.y-76,15,9,0,0,7);ctx.stroke();ctx.restore()}
function tickFortune(o,dt){const f=fighters[o.owner],e=fighters[1-o.owner];f.invincible=Math.max(0,f.invincible-dt);shots=[];if(o.t>.4){const u=clamp((o.t-.4)/.55,0,1);f.x=o.fromX+(clamp(e.x-52,55,W-55)-o.fromX)*u;f.y=o.fromY+(clamp(e.y+8,135,H-65)-o.fromY)*u;if(o.t>=1){while(o.pulses<10&&o.t>=1+o.pulses*.3&&running){o.pulses++;hit(e,30,f,o.color,0,false,'grapple');ring(e.x,e.y-75,o.color,14,'grip',.35)}if(o.t>=4&&!o.blast&&running){o.blast=true;hit(e,54,f,o.color,0,false,'grapple');ring(e.x,e.y-75,o.color,35,'impact',.7)}}}if(o.t>=o.duration||!running){if(!running)f.invincible=0;overflow=null;$('skillcut').classList.remove('overflow');fighters.forEach(v=>{v.turn=0;v.prevX=v.x;v.prevY=v.y;v.vx=v.vy=0})}}

function restoreHP(f,amount,show=false){if(f.char===37&&f.darkStandStarted)return 0;if(!running||!battleAlive(f)||amount<=0)return 0;const restored=Math.min(f.maxHp-f.hp,amount);f.hp+=restored;f.totalHealed+=restored;if(show&&restored>=.5){playSE('heal',f);labels.push({x:f.x,y:f.y-100,text:'+'+Math.round(restored),c:'#b5ffe4',life:1});burst(f.x,f.y-25,'#b5ffe4',12);f.healDisplayClock=.9}else f.healBank+=restored;return restored}
function tickRegen(f,dt){if(f.char!==6||!battleAlive(f)||!running)return;const boosted=Math.min(f.regenBoost,dt);f.regenBoost=Math.max(0,f.regenBoost-dt);restoreHP(f,12*dt+18*boosted);f.healDisplayClock-=dt;if(f.healDisplayClock<=0&&f.healBank>=1){playSE('heal',f);labels.push({x:f.x,y:f.y-100,text:'+'+Math.round(f.healBank),c:'#b5ffe4',life:.9});f.healBank=0;f.healDisplayClock=.9}}
function applyPoison(target,source,stacks=1){if(untouchable(target))return false;if(!running||!battleAlive(target))return;const active=target.poisonTime>0;target.poisonStacks=Math.min(5,target.poisonStacks+stacks);target.poisonTime=5;target.poisonSource=source.id;if(!active){target.poisonTick=.75;playSE('poison',source)}burst(target.x,target.y-25,'#a8ee7c',8)}
function tickPoison(f,dt){if(f.poisonTime<=0)return;const duration=Math.min(f.poisonTime,dt);f.poisonTime=Math.max(0,f.poisonTime-dt);f.poisonTick-=duration;while(f.poisonTick<=0&&running){f.poisonTick+=.75;const source=fighters[f.poisonSource];if(source)hit(f,(12+f.poisonStacks*8)*1.1,source,'#a8ee7c',0,true)}if(f.poisonTime<=0){f.poisonStacks=0;f.poisonTick=0;f.poisonSource=-1}}
function tickPools(dt){for(const pool of pools){withSelfSkill(pool.selfSkillOwner,()=>{if(!running)return;if(pool.kind==='annToxin'){tickAnnPool(pool,dt);return}if(pool.kind==='mud'){tickMudPool(pool,dt);return;}pool.life-=dt;pool.tick-=dt;if(pool.life>0&&pool.tick<=0){pool.tick+=.5;const e=skillEnemy(fighters[pool.owner]);if(Math.hypot(e.x-pool.x,e.y-pool.y)<pool.r){applyPoison(e,fighters[pool.owner]);ring(e.x,e.y-25,'#a8ee7c',25,'ring',.3)}}});}pools=pools.filter(pool=>pool.life>0)}
