function thunderKickEffect(f,e,c,n){if(!running)return;fx.push({x:f.x,y:f.y-32,angle:Math.atan2(e.y-f.y,e.x-f.x),n,c,r:72+n*12,kind:'thunderKick',life:.34,max:.34});ring(f.x,f.y-25,c,32,'ring',.25);playSE('thunder-kick',f)}
function drawThunderKick(q,progress){ctx.save();ctx.translate(q.x,q.y);ctx.rotate(q.angle+(q.n%2?1:-1)*(progress-.5)*.7);ctx.scale(1,.7);const r=q.r*(.8+progress*.35);ctx.fillStyle='#ffe88799';ctx.beginPath();ctx.arc(0,0,r,-1.05,1.05);ctx.arc(0,0,r*.62,1.05,-1.05,true);ctx.closePath();ctx.fill();ctx.strokeStyle=q.c;ctx.lineWidth=8;ctx.beginPath();ctx.arc(0,0,r,-1.05,1.05);ctx.stroke();ctx.strokeStyle='#fffde2';ctx.lineWidth=3;ctx.stroke();ctx.lineWidth=2;for(let n=0;n<4;n++){const a=-.8+n*.5,x=Math.cos(a)*r,y=Math.sin(a)*r;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+17,y-8);ctx.lineTo(x+12,y+5);ctx.lineTo(x+35,y);ctx.stroke()}ctx.restore()}
