function diamondProjectileTarget(s,ax,ay){if(selfSkillActive(s.selfSkillOwner))return fighters[s.selfSkillOwner];const enemy=fighters[1-s.owner];let target=enemy,nearest=Infinity;for(const v of [enemy,...diamondSoldiers.filter(v=>v.owner!==s.owner&&battleAlive(v)&&v.life>0)]){const rx=ax-v.prevX,ry=ay-v.prevY+20,dx=(s.x-ax)-(v.x-v.prevX),dy=(s.y-ay)-(v.y-v.prevY),den=dx*dx+dy*dy,u=den?clamp(-(rx*dx+ry*dy)/den,0,1):0;if(Math.hypot(rx+dx*u,ry+dy*u)<=hurtRadius(v)+s.r&&u<nearest){target=v;nearest=u}}return target}
function cloneRingColor(owner){
 const hex=colors[owner].slice(1),r=parseInt(hex.slice(0,2),16)/255,g=parseInt(hex.slice(2,4),16)/255,b=parseInt(hex.slice(4,6),16)/255;
 const high=Math.max(r,g,b),low=Math.min(r,g,b),delta=high-low,light=(high+low)/2;
 const hue=delta?(high===r?((g-b)/delta+6)%6:high===g?(b-r)/delta+2:(r-g)/delta+4)*60:0;
 const saturation=delta?delta/(1-Math.abs(2*light-1)):0;
 return 'hsl('+((hue+24)%360)+' '+(saturation*100)+'% '+(light*100)+'%)';
}
function drawDiamondSoldiers(){
 for(const v of diamondSoldiers){
  if(!battleAlive(v))return;
  const clone=!!v.hattanClone,full=clone||v.jend,ground=full?32:24,barWidth=full?66:54,barY=full?-124:-94;
  ctx.save();ctx.translate(v.x,v.y);ctx.globalAlpha=Math.min(1,v.life/.4);
  ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(0,ground,full?38:29,full?11:8,0,0,7);ctx.fill();
  ctx.strokeStyle=v.jend?'#e6a9c6':clone?cloneRingColor(v.owner):colors[v.owner];ctx.lineWidth=2;
  ctx.beginPath();ctx.ellipse(0,ground,full?41:32,full?14:10,0,0,7);ctx.stroke();
  ctx.shadowColor=v.order>0?'#f3d0ff':clone?colors[v.owner]:'#a4e9ff';ctx.shadowBlur=reduced?0:8;
  ctx.rotate(v.attack>0?Math.sin(v.attack*20)*.1:clamp(v.mx/2500,-.12,.12));
  if(v.petrified>0)ctx.filter='grayscale(1) brightness(.75)';
  if(v.jend){if(jendSprite)ctx.drawImage(jendSprite,-46,-109,92,138)}else if(clone)ctx.drawImage(sprites[26],-46,-109,92,138);
  else if(v.wordSoldier)drawWordSoldier(v);else ctx.drawImage(soldierImg,-36,-82,72,108);
  ctx.filter='none';ctx.shadowBlur=0;ctx.fillStyle='#243546';ctx.fillRect(-barWidth/2,barY,barWidth,4);
  ctx.fillStyle=colors[v.owner];ctx.fillRect(-barWidth/2,barY,barWidth*v.hp/v.maxHp,4);
  ctx.font='bold 9px sans-serif';ctx.textAlign='center';ctx.fillText((clone?(v.hordeClone?'OF分身 P':'分身 P'):v.jend?'ジェンド P':v.wordSoldier?'言霊兵 P':'兵士 P')+(v.owner+1)+(v.order>0?' / 強化':''),0,full?55:40);
  ctx.restore();
 }
}
function drawMuBarrier(f){ctx.save();ctx.strokeStyle='#bcefff';ctx.fillStyle='#d1dfff';ctx.globalAlpha=.14;ctx.beginPath();for(let n=0;n<6;n++){const a=n*Math.PI/3-Math.PI/6;ctx.lineTo(Math.cos(a)*61,Math.sin(a)*79-30)}ctx.closePath();ctx.fill();ctx.globalAlpha=.65;ctx.lineWidth=3;ctx.stroke();for(let n=0;n<3;n++){ctx.beginPath();ctx.moveTo(Math.cos(n*2.1)*61,Math.sin(n*2.1)*79-30);ctx.lineTo(0,-30);ctx.stroke()}ctx.restore()}
function initDiamondMeteor(o){const e=fighters[1-o.owner],cx=clamp(e.x+(e.mx||0)*.2,100,W-100),cy=clamp(e.y+(e.my||0)*.2,180,H-100);o.meteors=[[0,0],[-120,-80],[120,-80],[-110,90],[110,90],[0,0]].map(([x,y],i)=>({x:clamp(cx+x,65,W-65),y:clamp(cy+y,135,H-65),r:i===5?170:130,at:1+i*.28,damage:i===5?175:85,done:false}))}
function tickDiamondMeteor(o){const f=fighters[o.owner],e=fighters[1-o.owner];for(const m of o.meteors){if(!running)break;if(m.done||o.t<m.at)continue;m.done=true;ring(m.x,m.y-20,'#e3edff',m.r*.4,'impact',.65);burst(m.x,m.y-25,'#d6ebff',25);playSE('ultimate-impact',f);shake=reduced?0:12;for(const target of [e,...diamondSoldiers.filter(v=>v.owner!==f.id&&battleAlive(v))]){if(!running)break;if(Math.hypot(target.x-m.x,target.y-m.y)<m.r+hurtRadius(target))hit(target,m.damage,f,o.color,.4,false,'diamond')}}if(o.t>=o.duration||!running){overflow=null;$('skillcut').classList.remove('overflow');clearMotion()}}
function drawDiamondGem(x,y,size,rotation=0){ctx.save();ctx.translate(x,y);ctx.rotate(rotation);ctx.fillStyle='#d9f3ff';ctx.strokeStyle='#9cd8ff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-size);ctx.lineTo(size*.62,-size*.3);ctx.lineTo(size*.5,size*.32);ctx.lineTo(0,size);ctx.lineTo(-size*.5,size*.32);ctx.lineTo(-size*.62,-size*.3);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#afa8ed';ctx.beginPath();ctx.moveTo(0,-size);ctx.lineTo(size*.15,0);ctx.lineTo(0,size);ctx.lineTo(-size*.5,size*.32);ctx.closePath();ctx.fill();ctx.strokeStyle='#fff';ctx.beginPath();ctx.moveTo(-size*.62,-size*.3);ctx.lineTo(size*.15,0);ctx.lineTo(size*.62,-size*.3);ctx.moveTo(size*.15,0);ctx.lineTo(0,size);ctx.stroke();ctx.restore()}
function drawDiamondMeteor(o){for(const m of o.meteors){if(m.done){const life=o.t-m.at;if(life<.6){ctx.save();ctx.globalAlpha=(1-life/.6)*.7;ctx.strokeStyle='#dbeeff';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(m.x,m.y-20,m.r*(.3+life),m.r*(.2+life*.4),0,0,7);ctx.stroke();ctx.restore()}continue}ctx.save();ctx.strokeStyle='#d6eaff';ctx.fillStyle='#d1cdff';ctx.globalAlpha=.12;ctx.beginPath();ctx.ellipse(m.x,m.y-20,m.r,m.r*.6,0,0,7);ctx.fill();ctx.globalAlpha=.65;ctx.lineWidth=2;ctx.setLineDash([9,7]);ctx.stroke();ctx.setLineDash([]);const u=clamp((o.t-(m.at-.65))/.65,0,1);if(u>0){ctx.globalAlpha=.95;const y=m.y-20-(1-u)*530,x=m.x+(1-u)*110;ctx.strokeStyle='#e2efff88';ctx.lineWidth=m.r*.3;ctx.beginPath();ctx.moveTo(x+30,y-140);ctx.lineTo(x,y);ctx.stroke();drawDiamondGem(x,y,m.r*.4,-.2)}ctx.restore()}}


function stoneDefense(f){return f.defense/(f.char===46?1+f.moneyEaten*.0015:1)*(f.menouFragile>0?1.2:1)*(f.bloodRush>0?.35:1)*(f.char===37&&f.darkArmor>0?.55:1)*(f.char===34?1+f.hatTempo*.08:1)*(f.falseVerdict>0?1.2:1)/(f.petrified>0?1.5:1)}
function applyPetrify(target,source,duration){if(untouchable(target))return false;if(!running||target.phantom||!battleAlive(target)||target.invincible>0||target.overflowQueued||target.riftMirror>0)return false;target.petrified=Math.max(target.petrified||0,duration);target.dash=null;target.iceDash=null;target.follow=0;target.mx=target.my=target.vx=target.vy=0;releaseGrip(target);ring(target.x,target.y-25,'#c6c7ac',50,'cage',.5);return true}
function tickStoneAndRift(f,dt){const was=f.petrified>0;f.petrified=Math.max(0,(f.petrified||0)-dt);f.riftEvade=Math.max(0,(f.riftEvade||0)-dt);f.riftMirror=Math.max(0,(f.riftMirror||0)-dt);if(was&&!f.petrified&&!f.summon){f.turn=0;queueOverflow(f)}}
function startStoneField(f){stoneField={owner:f.id,left:5};for(const target of crowdOverflowTargets(f.id)){if(!running)break;const landed=hit(target,240,f,'#d1d1af',0,false,'stone');if(landed)applyPetrify(target,f,5)}if(!running)stoneField=null;else log('フェルマータ：全域石化5秒・CT停止・石化中の防御1.5倍')}
function tickStoneField(dt){if(!stoneField||!running)return;const field=stoneField;field.left=Math.max(0,field.left-dt);for(const target of crowdOverflowTargets(field.owner)){if(field.left>0&&!(target.petrified>0))applyPetrify(target,fighters[field.owner],field.left)}if(field.left<=0)stoneField=null}
function canTransfer(f){return !(f.shadowPin>0)&&battleAlive(f)&&!(f.petrified>0)&&f.frozen<=0&&f.rootTime<=0&&f.resinBind<=0&&f.mudBind<=0&&!f.grapple&&f.grabbedBy<0}
function portalFX(x,y,color){fx.push({x,y,c:color,r:52,kind:'portal',life:.5,max:.5})}
function transferTo(f,x,y){if(!canTransfer(f))return false;portalFX(f.x,f.y,colors[f.id]);f.x=clamp(x,55,W-55);f.y=clamp(y,135,H-65);f.prevX=f.x;f.prevY=f.y;f.mx=f.my=f.vx=f.vy=0;f.dash=null;f.iceDash=null;f.turn=0;portalFX(f.x,f.y,colors[f.id]);playSE('air',f);return true}
function blinkBehind(f,target,side){let dx=target.mx||0,dy=target.my||0;if(Math.hypot(dx,dy)<20){dx=f.x-target.x;dy=f.y-target.y}const len=Math.hypot(dx,dy)||1;dx/=len;dy/=len;return transferTo(f,target.x-dx*75-dy*side*45,target.y-dy*75+dx*side*45)}
function evadeTransfer(f,source){let spot=null;for(let n=0;n<6;n++){const candidate={x:65+Math.random()*(W-130),y:145+Math.random()*(H-220)};if(Math.hypot(candidate.x-source.x,candidate.y-source.y)>230&&Math.hypot(candidate.x-f.x,candidate.y-f.y)>170){spot=candidate;break}}if(!spot){const corners=[{x:65,y:145},{x:W-65,y:145},{x:65,y:H-75},{x:W-65,y:H-75}];spot=corners.reduce((a,b)=>Math.hypot(a.x-source.x,a.y-source.y)>Math.hypot(b.x-source.x,b.y-source.y)?a:b)}return transferTo(f,spot.x,spot.y)}
function interceptTransfer(f,source,damage,dot,type){if(f.char!==25)return false;if(f.riftMirror>0){portalFX(f.x,f.y,colors[f.id]);if(battleAlive(source)&&!source.overflowQueued&&!avoidDamage(source,false)){if(!applyDamageHP(source,damage))return true;f.totalReflected+=damage;labels.push({x:source.x,y:source.y-105,text:'転移反射 −'+damage,c:colors[source.id],life:.9});fx.push({x:f.x,y:f.y-30,tx:source.x,ty:source.y-30,c:colors[f.id],r:7,kind:'ribbon',life:.4,max:.4});if(!source.summon){queueOverflow(source);if(!battleAlive(source)&&!source.summon)finish()}}playSE('reflect',f);return true}if(f.riftEvade>0&&!dot&&!['field','judgment','pressure','cyclone','sureHit'].includes(type)&&canTransfer(f)){f.riftEvade=0;if(evadeTransfer(f,source)){f.invincible=Math.max(f.invincible,.14);labels.push({x:f.x,y:f.y-100,text:'転移回避',c:colors[f.id],life:.8});return true}}return false}
function drawRiftGate(x,y,r,c,t){ctx.save();ctx.translate(x,y);ctx.strokeStyle=c;ctx.fillStyle='#647bbf';ctx.globalAlpha*=.7;ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,0,r*.62,r,Math.sin(t*2)*.15,0,Math.PI*2);ctx.stroke();ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(0,0,r*.48,r*.85,-Math.sin(t*2)*.15,0,Math.PI*2);ctx.stroke();ctx.globalAlpha*=.15;ctx.fill();ctx.restore()}
function drawStoneCracks(){ctx.save();ctx.strokeStyle='#d4d4bd';ctx.lineWidth=2;for(let n=0;n<3;n++){const x=-25+n*24;ctx.beginPath();ctx.moveTo(x,-90);ctx.lineTo(x+12,-65);ctx.lineTo(x-3,-42);ctx.lineTo(x+8,-14);ctx.stroke()}ctx.fillStyle='#d1d1bb';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText('石化 / CT停止',0,-128);ctx.restore()}
function drawStoneField(){if(!stoneField)return;ctx.save();ctx.fillStyle='#999984';ctx.globalAlpha=.16;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#c7c7ae';ctx.lineWidth=2;ctx.globalAlpha=.3;for(let n=0;n<14;n++){const x=n*49,y=100+(n*173)%600;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+35,y-40);ctx.lineTo(x+52,y-18);ctx.lineTo(x+85,y-65);ctx.stroke()}ctx.globalAlpha=1;ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillStyle='#e1e1c9';ctx.fillText('フェルマータ / 全域石化 '+stoneField.left.toFixed(1)+'s',W/2,100);ctx.restore()}
function drawStoneCharge(o){ctx.save();ctx.globalAlpha=.3+o.t*.4;ctx.strokeStyle=o.color;ctx.lineWidth=5;for(let n=0;n<6;n++){ctx.beginPath();ctx.arc(W/2,H/2,40+n*55+o.t*140,0,Math.PI*2);ctx.stroke()}ctx.restore()}

function checkPasterForm(f){if(f.char!==21||f.fenrir||!battleAlive(f)||f.hp>f.maxHp*.6)return;f.fenrir=true;f.defense=roster[f.char].defense/1.1;const img=$('portrait'+f.id);img.src=fenrirImg.src;img.alt='パスター / フェンリル';ring(f.x,f.y-30,colors[f.id],90,'snow',1);ring(f.x,f.y-30,'#effcff',30,'ring',.8);cutin(f,'フェンリル変身',colors[f.id]);playSE('of-freeze',f);log('フェンリル化：攻撃力・防御力・氷弾・爪撃・範囲を強化')}
function frostClaw(f,e,c,r){fx.push({x:e.x,y:e.y-30,c,r,angle:Math.atan2(e.y-f.y,e.x-f.x),kind:'frostClaw',life:.35,max:.35});playSE('slash',f)}
function startFrostRun(f){checkPasterForm(f);f.frostRun=5;f.iceGap=0;f.iceContact=0;f.iceTrail=0;f.iceDash=null;f.dash=null;log('フローズンノヴァ：5秒間の超高速氷狼突撃')}
function prepareFrostRun(f,e,dt){if(f.char!==21||f.frostRun<=0)return;f.frostRun=Math.max(0,f.frostRun-dt);f.iceGap=Math.max(0,f.iceGap-dt);f.iceContact=Math.max(0,f.iceContact-dt);f.iceTrail-=dt;if(!f.frostRun){f.iceDash=null;f.dash=null;f.turn=0;return}if(f.iceTrail<=0){f.iceTrail=.065;ring(f.x,f.y-25,colors[f.id],30,'snow',.35)}if(f.iceDash||f.iceGap>0||f.dash||f.frozen>0||f.rootTime>0||f.resinBind>0||f.mudBind>0||f.grapple||f.grabbedBy>=0)return;const dx=e.x-f.x,dy=e.y-f.y,len=Math.hypot(dx,dy)||1,tx=clamp(e.x+dx/len*480,55,W-55),ty=clamp(e.y+dy/len*480,135,H-65),distance=Math.hypot(tx-f.x,ty-f.y);f.iceDash={x:f.x,y:f.y,tx,ty,t:0,duration:clamp(distance/2700,.12,.28)};f.follow=0;playSE('dash',f)}
function frostBodyHits(){if(!running)return;for(const f of fighters){if(f.char!==21||f.frostRun<=0||f.iceContact>0)continue;const e=fighters[1-f.id],x=f.prevX-e.prevX,y=f.prevY-e.prevY,dx=(f.x-f.prevX)-(e.x-e.prevX),dy=(f.y-f.prevY)-(e.y-e.prevY),den=dx*dx+dy*dy,u=den?clamp(-(x*dx+y*dy)/den,0,1):0;if(Math.hypot(x+dx*u,y+dy*u)<=hurtRadius(f)+hurtRadius(e)+18){f.iceContact=.38;hit(e,58,f,colors[f.id],.35,false,'thermal');ring(e.x,e.y-25,colors[f.id],55,'snow',.5)}if(!running)break}}
function ringFrozenAura(f,r=65){ctx.save();ctx.strokeStyle=colors[f.id];ctx.lineWidth=3;ctx.shadowColor=colors[f.id];ctx.shadowBlur=reduced?0:20;for(let n=0;n<3;n++){ctx.beginPath();ctx.ellipse(f.x,f.y-28,r*(1+n*.12),r*.6,n*.9+elapsed*3,0,Math.PI*2);ctx.stroke()}ctx.restore()}
function drawFrostClaw(q,progress){ctx.translate(q.x,q.y);ctx.rotate(q.angle);ctx.strokeStyle=q.c;ctx.lineWidth=9;for(let n=-1;n<=1;n++){ctx.beginPath();ctx.moveTo(-q.r*.65,n*26-q.r*.35);ctx.quadraticCurveTo(0,n*26+q.r*.4,q.r*.7,n*26-q.r*.3);ctx.stroke();ctx.strokeStyle='#f1fcff';ctx.lineWidth=3;ctx.stroke();ctx.strokeStyle=q.c;ctx.lineWidth=9}}
function stormFor(f){return thunderStorms.find(s=>s.owner===f.id)||null}
function electricBolt(x,y,tx,ty,c,powerful=false){const life=powerful?.4:.24;fx.push({x,y,tx,ty,c,r:powerful?9:5,powerful,kind:'lightning',life,max:life})}
function warnLightning(f,x,y,delay=.22,damage=16,radius=58,powerful=false){lightningZones.push({owner:f.id,x:clamp(x,35,W-35),y:clamp(y,115,H-40),delay,t:0,damage,radius,powerful,c:colors[f.id]})}
function startThunderStorm(owner){thunderStorms=thunderStorms.filter(s=>s.owner!==owner);thunderStorms.push({owner,left:ASHARA_OF.duration,rain:.04,rush:0,contact:0});playSE('thunder',fighters[owner]);log('天罰万雷：'+ASHARA_OF.duration+'秒間の雷雨と帯電突撃')}
function tickThunderStorms(dt){
 for(const s of thunderStorms){s.left=Math.max(0,s.left-dt);s.rain-=dt;s.rush=Math.max(0,s.rush-dt);s.contact=Math.max(0,s.contact-dt);const f=fighters[s.owner],e=fighters[1-s.owner];while(s.left>0&&s.rain<=0&&running){s.rain+=ASHARA_OF.rainInterval;warnLightning(f,e.x+e.mx*.16,e.y+e.my*.16,.22,ASHARA_OF.rainDamage);for(let n=0;n<2;n++)warnLightning(f,40+Math.random()*(W-80),130+Math.random()*(H-200),.22,ASHARA_OF.rainDamage)}}
 thunderStorms=thunderStorms.filter(s=>s.left>0&&battleAlive(fighters[s.owner]));
 for(const z of lightningZones){withSelfSkill(z.selfSkillOwner,()=>{if(!running)return;z.t+=dt;if(z.t>=z.delay){z.done=true;electricBolt(z.x,45,z.x,z.y-25,z.c,z.powerful);ring(z.x,z.y-25,z.c,z.powerful?55:26,'impact',.4);if(z.powerful)ring(z.x,z.y-25,'#fff5bb',20,'ring',.6);playSE(z.powerful?'thunder-crash':'thunder',fighters[z.owner]);const e=skillEnemy(fighters[z.owner]);if(Math.hypot(e.x-z.x,e.y-z.y)<=z.radius+hurtRadius(e))hit(e,z.damage,fighters[z.owner],z.c,.15,false,'thermal')}});}
 lightningZones=lightningZones.filter(z=>!z.done);
}
function prepareThunderRush(f,e){const s=stormFor(f);if(!s||s.rush>0||f.dash||f.frozen>0||f.rootTime>0||f.resinBind>0||f.mudBind>0||f.grapple||f.grabbedBy>=0)return;s.rush=.62;dash(f,e,-65)}
function thunderBodyHits(){if(!running)return;for(const s of thunderStorms){if(!running)break;if(s.contact>0)continue;const f=fighters[s.owner],e=fighters[1-s.owner],x=f.prevX-e.prevX,y=f.prevY-e.prevY,dx=(f.x-f.prevX)-(e.x-e.prevX),dy=(f.y-f.prevY)-(e.y-e.prevY),den=dx*dx+dy*dy,u=den?clamp(-(x*dx+y*dy)/den,0,1):0;if(Math.hypot(x+dx*u,y+dy*u)<=hurtRadius(f)+hurtRadius(e)+12){s.contact=ASHARA_OF.bodyInterval;hit(e,ASHARA_OF.bodyDamage,f,colors[f.id],.2);electricBolt(f.x,f.y-30,e.x,e.y-30,colors[f.id]);ring(e.x,e.y-25,colors[f.id],45,'impact',.4)}}}
function drawLightningWarnings(){for(const z of lightningZones){ctx.save();ctx.strokeStyle=z.c;ctx.fillStyle=z.c;ctx.globalAlpha=.08;ctx.beginPath();ctx.ellipse(z.x,z.y-25,z.radius,z.radius*.5,0,0,7);ctx.fill();ctx.globalAlpha=.35+Math.min(1,z.t/z.delay)*.45;ctx.lineWidth=2;ctx.setLineDash([7,6]);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.moveTo(z.x-9,z.y-47);ctx.lineTo(z.x+5,z.y-30);ctx.lineTo(z.x-4,z.y-16);ctx.stroke();if(z.powerful){ctx.globalAlpha=.6;ctx.beginPath();ctx.ellipse(z.x,z.y-25,z.radius*.7,z.radius*.35,0,0,7);ctx.stroke();ctx.fillStyle='#fff0a6';ctx.textAlign='center';ctx.font='bold 17px sans-serif';ctx.fillText('雷',z.x,z.y-19)}ctx.restore()}if(thunderStorms.length){ctx.save();ctx.fillStyle='#352b55';ctx.globalAlpha=.15;ctx.fillRect(0,45,W,48);ctx.globalAlpha=.7;ctx.fillStyle='#fff0a1';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.fillText(thunderStorms.map(s=>'P'+(s.owner+1)+' 天罰万雷 '+s.left.toFixed(1)+'s').join(' / '),W/2,78);ctx.restore()}}
function drawThunderCharge(o){const f=fighters[o.owner];ctx.save();ctx.strokeStyle=o.color;ctx.lineWidth=4;ctx.globalAlpha=.8;for(let n=0;n<7;n++){const a=n*Math.PI*2/7+o.t,x=f.x+Math.cos(a)*95,y=f.y-30+Math.sin(a)*95;electricPath(x,y,f.x,f.y-30)}ctx.restore()}
