function initBloomBeam(o){const f=fighters[o.owner],e=fighters[1-o.owner];o.beamX=f.x;o.beamY=f.y-30;o.beamAngle=Math.atan2(e.y-f.y,e.x-f.x);o.beamLength=Math.hypot(W,H)+120;o.beamHalfWidth=90;o.beamLocked=false}
